def _require_temporal_execution_type(
    config: EndpointConfig,
) -> TemporalExecutionType:
    if config.temporal_execution_type is None:
        raise ValueError(
            f"Temporal endpoint {config.name!r} requires temporalExecutionType"
        )
    return config.temporal_execution_type


def _custom_endpoint(config: EndpointConfig) -> CustomEndpointConfig:
    return CustomEndpointConfig(
        id=config.id,
        name=config.name,
        id_data_connector=config.id_data_connector,
        tracing_enabled=config.tracing_enabled or False,
        function_name=config.function_name,
        function_package=config.function_package,
        public_function=config.public_function or False,
        function_description=config.function_description,
        function_initializer_group=config.function_initializer_group,
        function_module=config.function_module,
        properties=config.properties,
    )


def _require_pool(config: PoolConfig | None, name: str) -> PoolConfig:
    if config is None:
        raise KeyError(f"pool '{name}' is missing from service config")
    return config


def _require_module(config: ModuleConfig | None, name: str) -> ModuleConfig:
    if config is None:
        raise KeyError(f"module '{name}' is missing from service config")
    return config


def _deep_merge(
    defaults: dict[str, Any],
    overrides: dict[str, Any],
) -> dict[str, Any]:
    result = dict(defaults)
    for key, override in overrides.items():
        current = result.get(key)
        if isinstance(current, dict) and isinstance(override, dict):
            result[key] = _deep_merge(current, override)
        else:
            result[key] = override
    return result


def _normalize_sections(obj: dict[str, Any]) -> dict[str, Any]:
    normalized = dict(obj)

    def values(name: str) -> list[dict[str, Any]]:
        section = normalized.get(name, {})
        if isinstance(section, dict):
            return list(section.values())
        if isinstance(section, list):
            return list(section)
        raise TypeError(f"config section '{name}' must be a mapping or list")

    for name in (
        "services", "streams", "links", "types", "pools", "modules", "endpoints",
    ):
        normalized[name] = values(name)
    normalized["dataConnectors"] = values("dataConnectors")
    return normalized


def _dump_default_config(value: Any) -> Any:
    if hasattr(value, "model_dump"):
        return value.model_dump(by_alias=True, exclude_none=True)
    if isinstance(value, dict):
        return {
            key: _dump_default_config(child)
            for key, child in value.items()
        }
    if isinstance(value, list):
        return [_dump_default_config(child) for child in value]
    return value